1190	// ===================== persistent continuous-ring prefill (hd128 bf16 TMA) =====================
1191	// FA3-style persistent kernel: each CTA grabs work-items off a static stride (work = blockIdx.x +
1192	// k*gridDim.x) and processes them in a loop. The win vs the per-tile prefill_kernel is that the K/V
1193	// ring is ONE CONTINUOUS stream across work-items -- PipelineState (the ring index g + its phase) is
1194	// declared once and NEVER reset per item, so the producer prefetches the next item's K/V into slots
1195	// the consumer just freed, with no per-item pipeline-fill bubble. (The earlier naive per-item-reinit
1196	// persistent attempt regressed precisely because it paid that fill + barrier-reinit cost every item.)
1197	//
1198	// Q is single-buffered with a barQf/barQe ping-pong (phase = witer&1): the producer waits barQe (the
1199	// consumer freed the prior Q), reloads Q -- via ONE async TMA box-set (rep==1, mapQ) so the reload is
1200	// cheap enough to hide behind the continuous ring; GQA/paged would fall back to the cp.async gather --
1201	// then signals barQf. To keep the ring primed across the boundary the producer issues the item's FIRST
1202	// K/V tile (empty-gated on the global g, NOT Q-gated) BEFORE the barQe wait, then floods the rest after
1203	// Q. Stage index / phase everywhere use the GLOBAL counter g so
1204	// producer and consumer stay in lock-step (both advance g by n_cnt per non-empty item, skip empties
1205	// identically). num_splits is implicitly 1 (prefill); no split-KV epilogue. TMA-only (routed so).
1206	template <typename TIn, typename TC, int HD, int HDV, bool USE_TMA, bool EXTRA, int STAGES, int CN = CTA_N,
1207	          int CM = CTA_M, int MINB = 1>
1208	__global__ __launch_bounds__(WG * (1 + CM / 64), MINB) void prefill_persist_kernel(
1209	        const TIn* __restrict__ Q, const TIn* __restrict__ K,
1210	        const TIn* __restrict__ V, TC* __restrict__ O, float* __restrict__ LSE,
1211	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1212	        const int* __restrict__ page_table,
1213	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1214	        int hkv, int rep, int total_q, int block_size, int page_stride,
1215	        float scale, int causal, float softcap, int win_l, int win_r,
1216	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1217	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1218	        int tiles_m, int batch, int* __restrict__ work_ctr,
1219	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapV,
1220	        const __grid_constant__ CUtensorMap mapQ) {
1221	    constexpr int HDsm  = ((HD  + 63) / 64) * 64;
1222	    constexpr int HDVsm = ((HDV + 63) / 64) * 64;
1223	    constexpr int KSTRIDE = CN * HDsm;
1224	    constexpr int VSTRIDE = CN * HDVsm;
1225	    constexpr int NCONS = (CM / 64) * WG;
1226	
1227	    constexpr int QBUF = 1;                    // Single Q buffer: rep==1 Q is reloaded via ONE async TMA
1228	                                               // (mapQ), fast enough that the STAGES-deep continuous K/V
1229	                                               // ring hides it across the item boundary. Double-Q hid the
1230	                                               // reload too but forced STAGES=2 (smem) -> starved K/V.
1231	    constexpr int SDEPTH = 2;                  // dynamic-scheduler work FIFO depth (producer lookahead)
1232	    TC* sQ = reinterpret_cast<TC*>(pf_smem);
1233	    TC* sK0 = sQ + QBUF * CM * HDsm;
1234	    TC* sV0 = sK0 + STAGES * KSTRIDE;
1235	    uint64_t* bars = reinterpret_cast<uint64_t*>(sV0 + STAGES * VSTRIDE);
1236	    uint64_t* full = bars;                     // [STAGES] count 1 (TMA tx-barrier)
1237	    uint64_t* empty = bars + STAGES;           // [STAGES] count NCONS
1238	    uint64_t* barQf = bars + 2 * STAGES;       // [QBUF] Q ready (producer -> consumers), count NumProd
1239	    uint64_t* barQe = bars + 2 * STAGES + QBUF;// [QBUF] Q free  (consumers -> producer), count NCONS
1240	    uint64_t* schF = bars + 2 * STAGES + 2 * QBUF;          // [SDEPTH] work ready (producer -> consumers)
1241	    uint64_t* schE = bars + 2 * STAGES + 2 * QBUF + SDEPTH; // [SDEPTH] slot free (consumers -> producer)
1242	    int* schW = reinterpret_cast<int*>(bars + 2 * STAGES + 2 * QBUF + 2 * SDEPTH);  // [SDEPTH] grabbed work idx
1243	
1244	    // Q via single async TMA when KV is contiguous (non-paged): rep==1 uses one 2D [CM,64] box per
1245	    // col-block; packed-GQA (rep>1, rep|CM) uses one 3D [64,rep,CM/rep] box per col-block (mapQ is built
1246	    // accordingly by the launcher). Both land in the same swizzled tile gather_row_k would have built, so
1247	    // the per-item Q reload is one async TMA (not a 128-row cp.async gather) -- which is what makes the
1248	    // persistent ring WIN for GQA/MQA (the gather reload serialized and lost to the per-tile grid).
1249	    // Paged / rep-not-dividing-CM keep the cp.async gather.
1250	    const bool tmaq     = USE_TMA && (page_table == nullptr) && (rep == 1);
1251	    const bool tmaq_gqa = USE_TMA && (page_table == nullptr) && (rep > 1) && (CM % rep == 0);
1252	    const int tid = threadIdx.x;
1253	    if (tid == 0) {
1254	#pragma unroll
1255	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], USE_TMA ? 1 : NumProd); mbar_init(&empty[s], NCONS); }
1256	#pragma unroll
1257	        for (int s = 0; s < QBUF; ++s) { mbar_init(&barQf[s], (tmaq || tmaq_gqa) ? 1 : NumProd); mbar_init(&barQe[s], NCONS); }
1258	#pragma unroll
1259	        for (int s = 0; s < SDEPTH; ++s) { mbar_init(&schF[s], 1); mbar_init(&schE[s], NCONS); }
1260	    }
1261	    __syncthreads();
1262	
1263	    // Dynamic LPT-free balancing: instead of static work=blockIdx.x+k*gridDim.x (which strands the
1264	    // causal triangular load -- early m-tiles are light, late ones heavy -- on fixed CTAs), each CTA
1265	    // pulls the next tile from a global atomic counter. The producer's lead thread grabs + publishes the
1266	    // index through a tiny smem FIFO (schW/schF/schE) so both warpgroups process the SAME stream while
1267	    // the GPU load-balances across CTAs the way the HW block scheduler does for the per-tile grid.
1268	    const int total_work = tiles_m * hkv * batch;
1269	    const int wg = tid / WG;
1270	
1271	    if (wg == 0) {
1272	        // ---------- producer ----------
1273	        producer_regs();
1274	        const int pt = tid;
1275	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1276	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1277	        const int pages = np ? 0 : (CN / block_size);
1278	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1279	        int g = 0, witer = 0;
1280	        for (int it = 0; ; ++it) {
1281	            // Pull the next tile from the global atomic; pt==0 grabs + publishes via schW, the producer
1282	            // warpgroup broadcasts it (bar.sync), and pt==0 signals schF for the consumers.
1283	            const int sslot = it % SDEPTH;
1284	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1285	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1286	            asm volatile("bar.sync 1, %0;\n" :: "r"(WG) : "memory");
1287	            const int work = schW[sslot];
1288	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1289	            if (work >= total_work) break;
1290	            PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1291	                                              causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1292	            if (!t.valid) continue;
1293	            const int gbase = g;
1294	            g += t.n_cnt;
1295	            const int bi = pf_bi(work, tiles_m, hkv);
1296	            const int last_pg = np ? 0 : ((t.seqlen_k - 1) / block_size);
1297	            const int ybase = np ? (cu_k ? cu_k[bi] : 0) : 0;         // non-paged: absolute key row of req bi
1298	            const int xk = t.hk * HD, xv = t.hk * HDV;
1299	            // load absolute key-tile nb into ring stage (gg % STAGES); pt==0 issues the TMA boxes.
1300	            // empty-gate on the GLOBAL gg keeps the ring a single continuous stream across items.
1301	            auto load_kv = [&](int gg, int nb) {
1302	                const int st = gg % STAGES;
1303	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1304	                TC* sKp = sK0 + st * KSTRIDE;
1305	                TC* sVp = sV0 + st * VSTRIDE;
1306	                mbar_expect_tx(&full[st], kv_bytes);
1307	                if (np) {
1308	                    // contiguous (non-paged): ONE [CN,64] box per col-block (same swizzled layout as paged).
1309	                    const int yk = ybase + nb * CN;
1310	#pragma unroll
1311	                    for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + bx * CB, &mapK, xk + bx * 64, yk, &full[st]);
1312	#pragma unroll
1313	                    for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + bx * CB, &mapV, xv + bx * 64, yk, &full[st]);
1314	                } else {
1315	                    for (int p = 0; p < pages; ++p) {
1316	                        int pg = nb * pages + p; if (pg > last_pg) pg = last_pg;
1317	                        int yrow = page_table[(long)bi * page_stride + pg] * block_size;
1318	                        int boff = p * block_size * 64;
1319	#pragma unroll
1320	                        for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + boff + bx * CB, &mapK, xk + bx * 64, yrow, &full[st]);
1321	#pragma unroll
1322	                        for (int bx = 0; bx < VBOX; ++bx) tma_box(sVp + boff + bx * CB, &mapV, xv + bx * 64, yrow, &full[st]);
1323	                    }
1324	                }
1325	            };
1326	            // (1) FIRST K/V tile before the Q-free wait -> primes the ring across the item boundary.
1327	            if (pt == 0) load_kv(gbase, t.n_lo);
1328	            // (2) Q into buffer slot witer%QBUF: wait the consumer freed it (item witer-QBUF), reload,
1329	            //     signal. rep==1 reloads via ONE TMA box-set; GQA/paged fall back to the cp.async gather.
1330	            const int qslot = witer % QBUF;
1331	            const int qcyc = witer / QBUF;
1332	            TC* sQs = sQ + qslot * (CM * HDsm);
1333	            if (witer >= QBUF) { int p = (qcyc - 1) & 1; while (!mbar_try_wait(&barQe[qslot], p)) {} }
1334	            if (tmaq) {
1335	                if (pt == 0) {
1336	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1337	                    const int yq = t.q0 + t.row0, xq = t.hk * HD;  // rep==1 -> qhead == hk
1338	                    constexpr int QBOX = HD / 64;
1339	#pragma unroll
1340	                    for (int bx = 0; bx < QBOX; ++bx) tma_box(sQs + bx * (CM * 64), &mapQ, xq + bx * 64, yq, &barQf[qslot]);
1341	                }
1342	            } else if (tmaq_gqa) {
1343	                if (pt == 0) {
1344	                    mbar_expect_tx(&barQf[qslot], (uint32_t)(CM * HD * (int)sizeof(TC)));
1345	                    // 3D box: token z = q0 + row0/rep (rep|CM => row0/rep is the tile's first token),
1346	                    // head y = hk*rep, col x = bx*64. One box per col-block fills the [CM,64] swizzle tile.
1347	                    const int zq = t.q0 + t.row0 / rep, yq = t.hk * rep;
1348	                    constexpr int QBOX = HD / 64;
1349	#pragma unroll
1350	                    for (int bx = 0; bx < QBOX; ++bx) tma_box3(sQs + bx * (CM * 64), &mapQ, bx * 64, yq, zq, &barQf[qslot]);
1351	                }
1352	            } else {
1353	                const int idx = t.row0 + pt;
1354	                const bool qval = idx < t.Mrows;
1355	                const int token = qval ? idx / rep : 0;
1356	                const int qhead = t.hk * rep + (qval ? idx % rep : 0);
1357	                const TIn* qsrc = Q + (long)(t.q0 + token) * q_row + (long)qhead * q_head;
1358	                gather_row_k<TIn, TC, HD, CM>(sQs, (uint32_t)__cvta_generic_to_shared(sQs), pt, qsrc, qval);
1359	                PF_PUBLISH(&barQf[qslot]);
1360	            }
1361	            // (3) remaining K/V tiles flood in behind Q.
1362	            if (pt == 0) for (int li = 1; li < t.n_cnt; ++li) load_kv(gbase + li, t.n_lo + li);
1363	            witer++;
1364	        }
1365	        return;
1366	    }
1367	
1368	    // ---------- consumers ----------
1369	    // NOTE: tried lifting the consumer to 240 by ceding the producer to 24 (256*240+128*24 = the 64512
1370	    // pool) -- it regressed broadly (gqa 0.91->0.87, large4k 0.82->0.78): the TMA producer needs its 40
1371	    // regs to issue/schedule ahead, and starving it stalls the whole ring. Consumer stays at 232.
1372	    consumer_regs<(MINB >= 2) ? 128 : 232>();
1373	    const int cwg = wg - 1;
1374	    const int wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
1375	    const int group = lane >> 2, tg = lane & 3;
1376	    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
1377	    const uint32_t sQ_base = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 4096 * (int)sizeof(TC));
1378	    const uint32_t sQ_slot = (uint32_t)(CM * HDsm * (int)sizeof(TC));   // stride between Q double-buffers
1379	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1380	    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
1381	    const uint32_t stK_bytes = (uint32_t)(KSTRIDE * (int)sizeof(TC));
1382	    const uint32_t stV_bytes = (uint32_t)(VSTRIDE * (int)sizeof(TC));
1383	
1384	    // Inter-WG ping-pong (mirrors prefill_kernel): the two consumer WGs process the SAME work item in
1385	    // lockstep on the shared K/V ring, so both hit the softmax (SFU) at the same time -> the tensor pipe
1386	    // idles (NCU large4k: barrier 31%, tensor 57% vs FA3 70%). Serializing the wgmma-ISSUE phase via two
1387	    // named barriers (8/9, cnt=256) staggers them by one step: while WG_a feeds the tensor core, WG_b runs
1388	    // softmax, and vice-versa. The token stays balanced across work items -- both WGs run the same n_cnt
1389	    // (same work index), so each does exactly one sync+arrive per inner-loop step. Gate: CM==128 (2
1390	    // consumer WGs) && HD==128. Big heads (192/256) are already tensor-pipe-saturated per tile so
1391	    // serializing the issue only adds barrier latency (-0.02 hd192/hd256). On the PERSIST path hd64
1392	    // measured a ~4% regression (1.25->1.20: its short HD=64 QK/PV leaves little softmax to overlap, so
1393	    // the extra barrier dominates) and hd96 was flat -- so unlike the per-tile kernel (HD<=128) the
1394	    // persist ping-pong is scoped to HD==128, where the win is real (local 0.89->0.96, causal 0.95->0.97,
1395	    // gqa 0.91->0.93).
1396	    constexpr bool PINGPONG = (CM == 128) && (HD == 128);
1397	    constexpr int PP_BASE = 8, PP_CNT = 2 * WG;   // barriers 8/9, 256 threads (both consumer WGs)
1398	    if constexpr (PINGPONG) { if (cwg == 0) nb_arrive(PP_BASE, PP_CNT); }  // WG0 issues first
1399	
1400	    int g = 0, witer = 0;
1401	    for (int it = 0; ; ++it) {
1402	        // Read the producer-grabbed work index for this slot, then free the slot for reuse.
1403	        const int sslot = it % SDEPTH;
1404	        { int p = (it / SDEPTH) & 1; while (!mbar_try_wait(&schF[sslot], p)) {} }
1405	        const int work = schW[sslot];
1406	        __threadfence_block();
1407	        mbar_arrive(&schE[sslot]);
1408	        if (work >= total_work) break;
1409	        PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1410	                                          causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1411	        if (!t.valid) continue;
1412	        const int gbase = g;
1413	        g += t.n_cnt;
1414	        const int qpos_lo = ((t.row0 + row_lo) / rep) + t.delta, qpos_hi = ((t.row0 + row_hi) / rep) + t.delta;
1415	
1416	        float acc_o[HDVsm / 2];
1417	#pragma unroll
1418	        for (int i = 0; i < HDVsm / 2; ++i) acc_o[i] = 0.f;
1419	        float m_r[2] = {-INFINITY, -INFINITY}, l_r[2] = {0.f, 0.f};
1420	        float s[CN / 2]; uint32_t P[CN / 4]; float sc[2];
1421	
1422	        // Q ready (buffer slot witer%QBUF, phase = (witer/QBUF)&1).
1423	        const int qslot = witer % QBUF;
1424	        const uint32_t sQ_wg = sQ_base + (uint32_t)qslot * sQ_slot;
1425	        { int p = (witer / QBUF) & 1; while (!mbar_try_wait(&barQf[qslot], p)) {} }
1426	        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1427	        // first key tile lives at the GLOBAL stage gbase%STAGES (phase from gbase), not stage 0.
1428	        { int st0 = gbase % STAGES, fp0 = (gbase / STAGES) & 1; while (!mbar_try_wait(&full[st0], fp0)) {} }
1429	        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1430	#pragma unroll
1431	        for (int i = 0; i < CN / 2; ++i) s[i] = 0.f;
1432	        qk_gemm_g<TC, HD, CN, CM>(s, sQ_wg, sK_a + (gbase % STAGES) * stK_bytes);
1433	        if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
1434	                               pf_mask_win<CN>(s, t.n_lo * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
1435	        else                   pf_mask<CN>(s, t.n_lo * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
1436	        sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, 0, t.s2);
1437	        sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, 0, t.s2);
1438	#pragma unroll
1439	        for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
1440	
1441	        for (int li = 1; li < t.n_cnt; ++li) {
1442	            const int gg = gbase + li, nb = t.n_lo + li;
1443	            const int st = gg % STAGES, pst = (gg - 1) % STAGES, fp = (gg / STAGES) & 1;
1444	            while (!mbar_try_wait(&full[st], fp)) {}
1445	            asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1446	            if constexpr (PINGPONG) nb_sync(PP_BASE + cwg, PP_CNT);          // wait my turn to issue
1447	            qk_rs_pv_g<TC, HD, HDVsm, CN, CM>(s, acc_o, P, sQ_wg, sK_a + st * stK_bytes, sV_a + pst * stV_bytes, sc);
1448	            if constexpr (PINGPONG) nb_arrive(PP_BASE + (1 - cwg), PP_CNT);  // release the other WG
1449	            wgmma_wait1();
1450	            if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
1451	                                   pf_mask_win<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
1452	            else                   pf_mask<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
1453	            sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, li, t.s2);
1454	            sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, li, t.s2);
1455	            wgmma_wait0();
1456	#pragma unroll
1457	            for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
1458	            mbar_arrive(&empty[pst]);
1459	        }
1460	        rescale_o_g(acc_o, sc);
1461	        pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + ((gbase + t.n_cnt - 1) % STAGES) * stV_bytes);
1462	        mbar_arrive(&empty[(gbase + t.n_cnt - 1) % STAGES]);
1463	        // free this Q double-buffer slot (after the last QK read in the mainloop; pv_final_g + the
1464	        // epilogue below touch no smem Q) so the producer can refill it for item witer+QBUF.
1465	        mbar_arrive(&barQe[qslot]);
1466	
1467	        // epilogue (num_splits==1: write O / LSE directly).
1468	#pragma unroll
1469	        for (int r = 0; r < 2; ++r) {
1470	            l_r[r] = quad_sum(l_r[r]);
1471	            bool bad = (l_r[r] == 0.f || l_r[r] != l_r[r]);
1472	            float inv = bad ? 0.f : 1.f / l_r[r];
1473	            const float invvd = inv * t.vd;
1474	            int idx = t.row0 + (r == 0 ? row_lo : row_hi);
1475	            bool val = idx < t.Mrows;
1476	            int token = idx / rep, qhead = t.hk * rep + idx % rep, qidx = t.q0 + token;
1477	            float lse_v = bad ? -INFINITY : m_r[r] * t.sc_eff + __logf(l_r[r]);
1478	            long obase = (long)qidx * o_row + (long)qhead * o_head;
1479	#pragma unroll
1480	            for (int c = 0; c < HDV / 8; ++c) {
1481	                int dv0 = 8 * c + 2 * tg;
1482	                uint32_t o = pack_2x<TC>(acc_o[c*4+r*2+0] * invvd, acc_o[c*4+r*2+1] * invvd);
1483	                if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
1484	            }
1485	            if (tg == 0 && val) LSE[(long)qhead * total_q + qidx] = lse_v;
1486	        }
1487	        witer++;
1488	    }
1489	}

