1692	// ===================== persistent continuous-ring native fp8 prefill =====================
1693	// fp8 analog of prefill_persist_kernel: collapses prefill_fp8_kernel's ~8.7-wave per-tile grid into
1694	// one persistent grid (the per-CTA cold-start that exposed 38% long_scoreboard on the fp8 dense config
1695	// disappears once the cp.async K/V ring streams continuously across work-items). Same fp8 mainloop as
1696	// prefill_fp8_kernel (cp.async K + plain-V staging -> in-smem transpose; SS QK then SS PV with P round-
1697	// tripped through smem) but driven by the atomic dynamic scheduler + single-buffered Q reload that the
1698	// bf16 persist path uses. No TMA (fp8 can't TMA-convert), so Q/K/V all reload via the cp.async gather.
1699	// Scoped to non-paged, num_splits==1; the per-tile prefill_fp8_kernel still covers paged/split/varlen.
1700	template <int HD, int HDV, bool EXTRA, int STAGES>
1701	__global__ __launch_bounds__(NThreads, 1) void prefill_fp8_persist_kernel(
1702	        const __nv_fp8_e4m3* __restrict__ Q, const __nv_fp8_e4m3* __restrict__ K,
1703	        const __nv_fp8_e4m3* __restrict__ V, __nv_bfloat16* __restrict__ O, float* __restrict__ LSE,
1704	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1705	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1706	        int hkv, int rep, int total_q,
1707	        float scale, int causal, float softcap, int win_l, int win_r,
1708	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1709	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1710	        int tiles_m, int batch, int* __restrict__ work_ctr) {
1711	    constexpr int CN = CTA_N, CM = CTA_M;
1712	    constexpr int KSTRIDE = CN * HD;           // one fp8 K tile (swizzled, elems=bytes)
1713	    constexpr int VSTRIDE = HDV * CN;          // one transposed fp8 V tile
1714	    constexpr int VstSTRIDE = CN * HDV;        // one PLAIN [key][dv] V staging tile
1715	    constexpr int QBUF = 1;                    // single-Q reload (cp.async, hidden by the K/V ring)
1716	    constexpr int SDEPTH = 2;                  // dynamic-scheduler work FIFO depth
1717	    constexpr int SCHED_BAR = 3;               // producer scheduler bar.sync id (consumer WGs use 1,2)
1718	
1719	    __nv_fp8_e4m3* sQ = reinterpret_cast<__nv_fp8_e4m3*>(pf_smem);
1720	    __nv_fp8_e4m3* sK0 = sQ + QBUF * CM * HD;
1721	    __nv_fp8_e4m3* sV0 = sK0 + STAGES * KSTRIDE;
1722	    __nv_fp8_e4m3* sP  = sV0 + STAGES * VSTRIDE;
1723	    __nv_fp8_e4m3* sVst0 = sP + CM * CN;
1724	    uint64_t* bars = reinterpret_cast<uint64_t*>(sVst0 + STAGES * VstSTRIDE);
1725	    uint64_t* full = bars;                      // [STAGES] count NumProd (K cp.async + Vt transposed)
1726	    uint64_t* empty = bars + STAGES;            // [STAGES] count NumCons
1727	    uint64_t* loaded = bars + 2 * STAGES;       // [STAGES] count NumProd (K + V-staging cp.async)
1728	    uint64_t* barQf = bars + 3 * STAGES;        // [QBUF] Q ready (producer -> consumers), count NumProd
1729	    uint64_t* barQe = bars + 3 * STAGES + QBUF; // [QBUF] Q free  (consumers -> producer), count NumCons
1730	    uint64_t* schF = bars + 3 * STAGES + 2 * QBUF;          // [SDEPTH] work ready (producer -> consumers)
1731	    uint64_t* schE = bars + 3 * STAGES + 2 * QBUF + SDEPTH; // [SDEPTH] slot free (consumers -> producer)
1732	    int* schW = reinterpret_cast<int*>(bars + 3 * STAGES + 2 * QBUF + 2 * SDEPTH);  // [SDEPTH] grabbed work idx
1733	
1734	    const int tid = threadIdx.x;
1735	    if (tid == 0) {
1736	#pragma unroll
1737	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], NumProd); mbar_init(&empty[s], NumCons); mbar_init(&loaded[s], NumProd); }
1738	#pragma unroll
1739	        for (int s = 0; s < QBUF; ++s) { mbar_init(&barQf[s], NumProd); mbar_init(&barQe[s], NumCons); }
1740	#pragma unroll
1741	        for (int s = 0; s < SDEPTH; ++s) { mbar_init(&schF[s], 1); mbar_init(&schE[s], NumCons); }
1742	    }
1743	    __syncthreads();
1744	
1745	    const int total_work = tiles_m * hkv * batch;
1746	    const int wg = tid / WG;
1747	
1748	    if (wg == 0) {
1749	        // ---------- producer: cp.async Q/K (swizzled) + V (plain staging) -> in-smem transpose ----------
1750	        producer_regs();
1751	        const int pt = tid;
1752	        const uint32_t sVst_a = (uint32_t)__cvta_generic_to_shared(sVst0);
1753	        const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1754	        int g = 0, witer = 0;
1755	        for (int it = 0; ; ++it) {
1756	            const int sslot = it % SDEPTH;
1757	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1758	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1759	            asm volatile("bar.sync %0, %1;\n" :: "r"(SCHED_BAR), "r"(WG) : "memory");
1760	            const int work = schW[sslot];
1761	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1762	            if (work >= total_work) break;
1763	            PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1764	                                              causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1765	            if (!t.valid) continue;
1766	            const int bi = pf_bi(work, tiles_m, hkv);
1767	            const long ybase = (long)(cu_k ? cu_k[bi] : 0);            // non-paged: absolute key row of req bi
1768	            // issue cp.async loads for GLOBAL tile gg (key tile nb) into stage gg%STAGES.
1769	            auto issue_load = [&](int gg, int nb) {
1770	                const int st = gg % STAGES;
1771	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1772	                const int key = nb * CN + pt;
1773	                const bool kval = key < t.seqlen_k;
1774	                const long krow = ybase + (kval ? key : 0);
1775	                const __nv_fp8_e4m3* ksrc = K + krow * k_row + (long)t.hk * k_head;
1776	                const __nv_fp8_e4m3* vsrc = V + krow * v_row + (long)t.hk * v_head;
1777	                gather_row_k8_cp<HD>(sK0 + st * KSTRIDE, sK_a + (uint32_t)(st * KSTRIDE), pt, ksrc, kval);
1778	                gather_row_plain8_cp<HDV>(sVst0 + st * VstSTRIDE, sVst_a + (uint32_t)(st * VstSTRIDE), pt, vsrc, kval);
1779	                cp_async_mbar_arrive(&loaded[st]);
1780	            };
1781	            // (1) prime the item's first K/V tile (continuous ring) before the Q-free wait.
1782	            issue_load(g, t.n_lo);
1783	            // (2) Q into the single buffer: wait the consumer freed it, reload, signal.
1784	            const int qslot = witer % QBUF;
1785	            if (witer >= QBUF) { int p = ((witer / QBUF) - 1) & 1; while (!mbar_try_wait(&barQe[qslot], p)) {} }
1786	            {
1787	                const int idx = t.row0 + pt;
1788	                const bool qval = idx < t.Mrows;
1789	                const int token = qval ? idx / rep : 0;
1790	                const int qhead = t.hk * rep + (qval ? idx % rep : 0);
1791	                const __nv_fp8_e4m3* qsrc = Q + (long)(t.q0 + token) * q_row + (long)qhead * q_head;
1792	                gather_row_k8_cp<HD>(sQ + qslot * (CM * HD),
1793	                                     (uint32_t)__cvta_generic_to_shared(sQ + qslot * (CM * HD)), pt, qsrc, qval);
1794	                cp_async_mbar_arrive(&barQf[qslot]);
1795	            }
1796	            // (3) remaining K/V tiles flood in behind Q; transpose each staged tile into sVt.
1797	            for (int li = 0; li < t.n_cnt; ++li) {
1798	                if (li + 1 < t.n_cnt) issue_load(g + li + 1, t.n_lo + li + 1);   // prefetch next tile
1799	                const int gg = g + li, st = gg % STAGES, fp = (gg / STAGES) & 1;
1800	                while (!mbar_try_wait(&loaded[st], fp)) {}
1801	                asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");   // V-staging cp.async -> smem reads
1802	                transpose_v_smem8<HDV>(sV0 + st * VSTRIDE, sVst0 + st * VstSTRIDE, pt);
1803	                mbar_arrive(&full[st]);                                          // K (cp.async) + Vt (transposed) ready
1804	            }
1805	            g += t.n_cnt;
1806	            witer++;
1807	        }
1808	        return;
1809	    }
1810	
1811	    // ---------- consumers ----------
1812	    consumer_regs();
1813	    const int cwg = wg - 1;
1814	    const int wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
1815	    const int group = lane >> 2, tg = lane & 3;
1816	    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
1817	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1818	    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
1819	    const uint32_t sP_wg = (uint32_t)__cvta_generic_to_shared(sP) + (uint32_t)(cwg * 8192);
1820	    const int barid = 1 + cwg;
1821	
1822	    int g = 0, witer = 0;
1823	    for (int it = 0; ; ++it) {
1824	        const int sslot = it % SDEPTH;
1825	        { int p = (it / SDEPTH) & 1; while (!mbar_try_wait(&schF[sslot], p)) {} }
1826	        const int work = schW[sslot];
1827	        __threadfence_block();
1828	        mbar_arrive(&schE[sslot]);
1829	        if (work >= total_work) break;
1830	        PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1831	                                          causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1832	        if (!t.valid) continue;
1833	        const int gbase = g;
1834	        g += t.n_cnt;
1835	        const int qpos_lo = ((t.row0 + row_lo) / rep) + t.delta, qpos_hi = ((t.row0 + row_hi) / rep) + t.delta;
1836	
1837	        float acc_o[HDV / 2];
1838	#pragma unroll
1839	        for (int i = 0; i < HDV / 2; ++i) acc_o[i] = 0.f;
1840	        float m_r[2] = {-INFINITY, -INFINITY}, l_r[2] = {0.f, 0.f};
1841	        float s[64]; float sc[2];
1842	
1843	        const int qslot = witer % QBUF;
1844	        const uint32_t sQ_wg = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(qslot * CM * HD + cwg * 8192);
1845	        { int p = (witer / QBUF) & 1; while (!mbar_try_wait(&barQf[qslot], p)) {} }
1846	        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1847	
1848	        for (int li = 0; li < t.n_cnt; ++li) {
1849	            const int nb = t.n_lo + li, gg = gbase + li;
1850	            const int st = gg % STAGES, fp = (gg / STAGES) & 1;
1851	            while (!mbar_try_wait(&full[st], fp)) {}
1852	            asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1853	            qk_fp8_ss<HD>(s, sQ_wg, sK_a + st * (uint32_t)KSTRIDE);
1854	            wgmma_wait0();
1855	            wg_fence_c(s);
1856	            if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap(s, t.sc_eff, softcap);
1857	                                   pf_mask_win(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
1858	            else                   pf_mask(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
1859	            sc[0] = softmax_stats(s, m_r, l_r, 0, li, t.s2);
1860	            sc[1] = softmax_stats(s, m_r, l_r, 1, li, t.s2);
1861	            rescale_o_g(acc_o, sc);
1862	            scatter_P_fp8(s, sP_wg, warp, group, tg);
1863	            wg_barrier(barid);
