1865	            pv_fp8_ss(acc_o, sP_wg, sV_a + st * (uint32_t)VSTRIDE);
1866	            wgmma_wait0();
1867	            wg_fence_c(acc_o);
1868	            mbar_arrive(&empty[st]);
1869	        }
1870	        // free this Q buffer (all qk reads done) so the producer can refill it for item witer+QBUF.
1871	        mbar_arrive(&barQe[qslot]);
1872	
1873	#pragma unroll
1874	        for (int r = 0; r < 2; ++r) {
1875	            l_r[r] = quad_sum(l_r[r]);
1876	            bool bad = (l_r[r] == 0.f || l_r[r] != l_r[r]);
1877	            float inv = bad ? 0.f : 1.f / l_r[r];
