1883	            long obase = (long)qidx * o_row + (long)qhead * o_head;
1884	#pragma unroll
1885	            for (int c = 0; c < HDV / 8; ++c) {
1886	                int dv0 = 8 * c + 2 * tg;
1887	                uint32_t o = pack_bf16(acc_o[c*4+r*2+0] * invvd, acc_o[c*4+r*2+1] * invvd);
1888	                if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
1889	            }
