600	template <int N>
601	__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
602	#pragma unroll
603	    for (int c = 0; c < N / 4; ++c) {
604	        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
605	        acc_o[c*4+2] *= sc[1]; acc_o[c*4+3] *= sc[1];
606	    }
607	}
608	// PV: emit ceil(HDVsm/64) 64-col boxes. V box b starts CN*64 elems (one CN-row col-block) apart;
609	// the descriptor leading-byte-offset spans that same col-block (CN*64*2 = CN*128 bytes).
610	template <typename T, int HDV, int CN>
611	__device__ __forceinline__ void pv_boxes(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
612	    constexpr uint32_t LBO = (uint32_t)(CN * 128), BOX = (uint32_t)(CN * 128);
613	    pv_box64<T, 0, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base, LBO, SW_V_SBO, 1));
614	    if constexpr (HDV >= 128) pv_box64<T, 32, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 1*BOX, LBO, SW_V_SBO, 1));
