template <int N>
__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
#pragma unroll
    for (int c = 0; c < N / 4; ++c) {
        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
        acc_o[c*4+2] *= sc[1]; acc_o[c*4+3] *= sc[1];
    }
}
