859	// bi is recovered from work where needed (page_table indexing); keep it out of PfTile to save a reg.
860	__device__ __forceinline__ int pf_bi(int work, int tiles_m, int hkv) { return work / (tiles_m * hkv); }
861	
862	// Split-KV: an empty/masked/padded CTA (no key tiles to process) must still stamp -inf into its
863	// LSEpart rows so combine_kernel drops it. Doing it here lets LSEpart be a plain at::empty -- it
864	// replaces a per-call host-side at::full that memset the WHOLE scratch (an extra ~2us fill kernel +
865	// launch every decode call) even though the typical split has no empties. Only the consumer
866	// warpgroups carry rows; the (cwg/warp/group, tg==0) -> (qidx,qhead) mapping mirrors the epilogue.
867	__device__ __forceinline__ void emit_empty_lse(float* __restrict__ LSEpart, int tid, int split, int hq,
868	        int row0, int Mrows, int hk, int rep, int q0, int total_q) {
869	    if (tid < WG) return;                              // producer warpgroup carries no rows
870	    const int cwg = tid / WG - 1, wt = tid % WG, wp = wt >> 5, ln = wt & 31;
871	    if ((ln & 3) != 0) return;                         // only tg==0 writes the LSE (matches epilogue)
872	#pragma unroll
873	    for (int r = 0; r < 2; ++r) {
874	        const int idx = row0 + cwg * 64 + wp * 16 + (ln >> 2) + (r ? 8 : 0);
875	        if (idx < Mrows)
876	            LSEpart[((long)split * hq + hk * rep + idx % rep) * total_q + q0 + idx / rep] = -INFINITY;
877	    }
878	}
