    if (jlo < jhi) load_key(jlo, kxA, vxA);
    for (int j = jlo; j < jhi; ++j) {
        const bool A = ((j - jlo) & 1) == 0;
        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
