        if (mi >= M) break;
        const int qpos = mi / rep, r = mi % rep;
        const int head = hk * rep + r, qidx = q0 + qpos;
        const float inv = lrow[mi] > 0.f ? 1.f / lrow[mi] : 0.f;
        float* op = Opart + (((long)split * total_q + qidx) * hq + head) * HDV;
#pragma unroll
