    uint64_t d = 0; d |= (uint64_t)((a >> 4) & 0x3FFFu); d |= (uint64_t)((lbo >> 4) & 0x3FFFu) << 16;
    d |= (uint64_t)((sbo >> 4) & 0x3FFFu) << 32; d |= (uint64_t)(lt & 0x3u) << 62; return d;
}
