    float s[64];
#pragma unroll
    for (int c = 0; c < 16; ++c)
        for (int r2 = 0; r2 < 2; ++r2)
            for (int p = 0; p < 2; ++p) {
                int row = cwg * 64 + warp * 16 + group + 8 * r2;
                int key = 8 * c + 2 * tg + p;
                s[c * 4 + r2 * 2 + p] = P[row * CTA_N + key];
