if (!t.valid) continue;
const int bi = pf_bi(work, tiles_m, hkv);
const long ybase = (long)(cu_k ? cu_k[bi] : 0);            // non-paged: absolute key row of req bi
// issue cp.async loads for GLOBAL tile gg (key tile nb) into stage gg%STAGES.
auto issue_load = [&](int gg, int nb) {
    const int st = gg % STAGES;
    if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
    const int key = nb * CN + pt;
    const bool kval = key < t.seqlen_k;
    const long krow = ybase + (kval ? key : 0);
    const __nv_fp8_e4m3* ksrc = K + krow * k_row + (long)t.hk * k_head;
    const __nv_fp8_e4m3* vsrc = V + krow * v_row + (long)t.hk * v_head;
    gather_row_k8_cp<HD>(sK0 + st * KSTRIDE, sK_a + (uint32_t)(st * KSTRIDE), pt, ksrc, kval);
    gather_row_plain8_cp<HDV>(sVst0 + st * VstSTRIDE, sVst_a + (uint32_t)(st * VstSTRIDE), pt, vsrc, kval);
    cp_async_mbar_arrive(&loaded[st]);
};
// (1) prime the item's first K/V tile (continuous ring) before the Q-free wait.

