1547	// ===================== native fp8 (e4m3) prefill kernel =====================
1548	// Same warp-specialized shape as prefill_kernel (1 producer WG + 2 consumer WGs of 64 q-rows each)
1549	// but the matmuls run natively on the fp8 tensor core (~2x bf16). Q/K are stored as raw fp8 in the
1550	// 1-byte 128B-swizzle smem tile; V is transposed to the K-major [dv][key] tile the fp8 PV needs;
1551	// the softmax probabilities P are downcast to fp8 and round-tripped through smem so PV is an SS GEMM
1552	// (P and V both from smem descriptors -> no register-fragment puzzle). Output is bf16.
1553	template <int HD, int HDV, bool EXTRA, int STAGES>
1554	__global__ __launch_bounds__(NThreads, 1) void prefill_fp8_kernel(
1555	        const __nv_fp8_e4m3* __restrict__ Q, const __nv_fp8_e4m3* __restrict__ K,
1556	        const __nv_fp8_e4m3* __restrict__ V, __nv_bfloat16* __restrict__ O, float* __restrict__ LSE,
1557	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1558	        const int* __restrict__ page_table,
1559	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1560	        int hkv, int rep, int total_q, int block_size, int page_stride,
1561	        float scale, int causal, float softcap, int win_l, int win_r,
1562	        int num_splits, float* __restrict__ Opart, float* __restrict__ LSEpart,
1563	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1564	        const float* __restrict__ v_descale, int ds_b, int ds_h) {
1565	    constexpr int KSTRIDE = CTA_N * HD;        // one fp8 K tile (elems=bytes)
1566	    constexpr int VSTRIDE = HDV * CTA_N;       // one transposed fp8 V tile
1567	    const int m_block = blockIdx.x / num_splits, split = blockIdx.x % num_splits, hk = blockIdx.y, bi = blockIdx.z;
1568	    const int q0 = cu_q[bi];
1569	    const int seqlen_q = cu_q[bi + 1] - q0;
1570	    const int seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
1571	    const int Mrows = seqlen_q * rep;
1572	    const int row0 = m_block * CTA_M;
1573	    if (row0 >= Mrows) return;                          // padded m_block: no valid rows
1574	    const int delta = seqlen_k - seqlen_q;
1575	    const long ds_idx = (long)bi * ds_b + (long)hk * ds_h;
1576	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
1577	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
1578	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
1579	    const float sc_eff = scale * qd * kd;
1580	    const float s2 = sc_eff * float(M_LOG2E);
1581	    const int top = (row0 + CTA_M - 1 < Mrows - 1) ? (row0 + CTA_M - 1) : (Mrows - 1);
1582	    const int qabs_max = (top / rep) + delta;
1583	    const int n_max = causal ? ((qabs_max + 1 + CTA_N - 1) / CTA_N) : ((seqlen_k + CTA_N - 1) / CTA_N);
1584	    // Empty CTA stamps -inf into its split-KV LSEpart rows (see emit_empty_lse) so LSEpart can be a
1585	    // plain at::empty; single-split exits. Detected uniformly, before the mbar_init/__syncthreads.
1586	    int n_lo = 0, n_cnt = n_max;
1587	    bool empty_cta = (seqlen_k <= 0) || (n_max <= 0);
1588	    if (!empty_cta && num_splits > 1) {
1589	        const int per = (n_max + num_splits - 1) / num_splits;
1590	        n_lo = split * per;
1591	        if (n_lo >= n_max) empty_cta = true;
1592	        else n_cnt = (n_max - n_lo < per) ? (n_max - n_lo) : per;
1593	    }
1594	    if (empty_cta) {
1595	        if (num_splits > 1)
1596	            emit_empty_lse(LSEpart, (int)threadIdx.x, split, hkv * rep, row0, Mrows, hk, rep, q0, total_q);
1597	        return;
1598	    }
