// 2D TMA L2 prefetch: bring the box at (x,y) into L2 only (no smem, no mbarrier). Lets the producer
// run the L2 prefetch DEEPER than the smem ring -- so a shallow (STAGES=2) smem ring sees L2 hits
// instead of cold DRAM, which is what lets a wide CN/2-stage tile not starve on the big-head loads.
__device__ __forceinline__ void tma_prefetch(const CUtensorMap* map, int x, int y) {
    asm volatile("cp.async.bulk.prefetch.tensor.2d.L2.global.tile [%0, {%1, %2}];\n"
                 :: "l"(map), "r"(x), "r"(y) : "memory");
}

