file.content:
        if constexpr (KVSPLIT) mbar_arrive(&empty[gbase % STAGES]);
        if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
                               pf_mask_win<CN>(s, t.n_lo * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
        else                   pf_mask<CN>(s, t.n_lo * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
        sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, 0, t.s2);
        sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, 0, t.s2);
#pragma unroll
        for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);

        for (int li = 1; li < t.n_cnt; ++li) {
            const int gg = gbase + li, nb = t.n_lo + li;
            const int st = gg % STAGES, pst = (gg - 1) % STAGES, fp = (gg / STAGES) & 1;
            const int pstV = KVSPLIT ? ((gg - 1) % VST) : pst;       // V[gg-1] slot (own ring when split)
            while (!mbar_try_wait(&full[st], fp)) {}                 // K[gg] ready (for this QK)
            // Split-ring: PV consumes V[gg-1] from its own ring -> wait its fullV (coupled mode's V is
            // transitively ready via the K full[] wait, so this extra wait is split-only).
            if constexpr (KVSPLIT) { int fpv = ((gg - 1) / VST) & 1; while (!mbar_try_wait(&fullV[pstV], fpv)) {} }
            asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
            if constexpr (PINGPONG) nb_sync(PP_BASE + cwg, PP_CNT);          // wait my turn to issue
            qk_rs_pv_g<TC, HD, HDVsm, CN, CM>(s, acc_o, P, sQ_wg, sK_a + st * stK_bytes, sV_a + pstV * stV_bytes, sc);
            if constexpr (PINGPONG) nb_arrive(PP_BASE + (1 - cwg), PP_CNT);  // release the other WG
            wgmma_wait1();
            if constexpr (KVSPLIT) mbar_arrive(&empty[st]);          // K[gg] done (QK) -> free its stage early
            if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
                                   pf_mask_win<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, win_l, win_r, tg); }
            else                   pf_mask<CN>(s, nb * CN, qpos_lo, qpos_hi, t.seqlen_k, causal, tg);
            sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, li, t.s2);
            sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, li, t.s2);
            wgmma_wait0();
#pragma unroll
            for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
            mbar_arrive(&emptyV[pstV]);                              // V[gg-1] done (PV) -> free its stage
        }
        rescale_o_g(acc_o, sc);
        const int lpstV = KVSPLIT ? ((gbase + t.n_cnt - 1) % VST) : ((gbase + t.n_cnt - 1) % STAGES);
        // Split-ring: wait the last block's V (its own ring) before the final PV (coupled mode already
        // waited it via the K full[] path). Its K was freed in-loop right after its QK.
        if constexpr (KVSPLIT) { int g2 = gbase + t.n_cnt - 1; int fpv = (g2 / VST) & 1; while (!mbar_try_wait(&fullV[lpstV], fpv)) {} }
        pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + lpstV * stV_bytes);
        mbar_arrive(&emptyV[lpstV]);

