1328	        // ---------- producer ----------
1329	        producer_regs();
1330	        const int pt = tid;
1331	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1332	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1333	        const int pages = np ? 0 : (CN / block_size);
1334	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1335	        const uint32_t k_bytes = (uint32_t)(CN * HD * sizeof(TC)), v_bytes = (uint32_t)(CN * HDV * sizeof(TC));
1336	        int g = 0, witer = 0;
1337	        for (int it = 0; ; ++it) {
1338	            // Pull the next tile from the global atomic; pt==0 grabs + publishes via schW, the producer
1339	            // warpgroup broadcasts it (bar.sync), and pt==0 signals schF for the consumers.
1340	            const int sslot = it % SDEPTH;
1341	            if (pt == 0 && it >= SDEPTH) { int ep = ((it / SDEPTH) - 1) & 1; while (!mbar_try_wait(&schE[sslot], ep)) {} }
1342	            if (pt == 0) schW[sslot] = atomicAdd(work_ctr, 1);
1343	            asm volatile("bar.sync 1, %0;\n" :: "r"(WG) : "memory");
1344	            const int work = schW[sslot];
1345	            if (pt == 0) { __threadfence_block(); mbar_arrive(&schF[sslot]); }
1346	            if (work >= total_work) break;
1347	            PfTile t = pf_work<CN, CM, EXTRA>(work, tiles_m, hkv, rep, cu_q, cu_k, seqused_k,
1348	                                              causal, win_l, win_r, scale, q_descale, k_descale, v_descale, ds_b, ds_h);
1349	            if (!t.valid) continue;
1350	            const int gbase = g;
1351	            g += t.n_cnt;
1352	            const int bi = pf_bi(work, tiles_m, hkv);
1353	            const int last_pg = np ? 0 : ((t.seqlen_k - 1) / block_size);
1354	            const int ybase = np ? (cu_k ? cu_k[bi] : 0) : 0;         // non-paged: absolute key row of req bi
1355	            const int xk = t.hk * HD, xv = t.hk * HDV;
1356	            // load absolute key-tile nb into ring stage (gg % STAGES); pt==0 issues the TMA boxes.
1357	            // empty-gate on the GLOBAL gg keeps the ring a single continuous stream across items.
1358	            // K and V box issue (np = one [CN,64] box/col-block; paged = per-page boxes). Split into two
1359	            // helpers so the split-ring path can issue K's TMA the moment its own slot frees, without
1360	            // waiting on V's slot -- that independence is what gives the producer K-prefetch lead.
1361	            auto issue_k = [&](int nb, TC* sKp, uint64_t* kbar) {
1362	                if (np) {
1363	                    const int yk = ybase + nb * CN;
1364	#pragma unroll
1365	                    for (int bx = 0; bx < KBOX; ++bx) tma_box(sKp + bx * CB, &mapK, xk + bx * 64, yk, kbar);
1366	                } else {
