#define PF_LAUNCH(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_, TMA_, EXTRA_)                                   \
    launch_prefill_t<TIn, TC, HD_, HDV_, TMA_, EXTRA_, ST_, CN_, CM_, 1, KVS_, VST_>(q, k, v, out, lse, cu_q, cu_k, seqused_k, \
        page_table, mapK, mapV, hkv, rep, total_q, block_size, page_stride, tiles_m, b, scale,          \
        causal, softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,      \
        1, nullptr, nullptr, qd, kd, vd, ds_b, ds_h, stream)
#define PF_DISPATCH_S(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_)                                             \
    do {                                                                                                \
        bool extra = (softcap > 0.0) || (win_l >= 0) || (win_r >= 0);                                   \
        if (use_tma) { if (extra) PF_LAUNCH(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_, true, true);  else PF_LAUNCH(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_, true, false); }   \
        else         { if (extra) PF_LAUNCH(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_, false, true); else PF_LAUNCH(HD_, HDV_, ST_, CN_, CM_, KVS_, VST_, false, false); }  \
    } while (0)
#define PF_DISPATCH(HD_, HDV_, ST_, CN_, CM_) PF_DISPATCH_S(HD_, HDV_, ST_, CN_, CM_, false, ST_)
    if (hd == 64 && hdv == 64)        PF_DISPATCH(64, 64, WS_STAGES, 128, 128);
    else if (hd == 96 && hdv == 96)   PF_DISPATCH(96, 96, WS_STAGES, 128, 128);
    // hd128: the windowed (SWA) EXTRA mask path's extra live registers tip the wide CM=128/CN=128
    // consumer into spill-RELOADS (NCU: local spillLD 4608 -> long_scoreboard 37%, vs gqa EXTRA=false
    // spillLD 0). A narrow CN=64 halves the score-register footprint s[CN/2] -> no spill, and since the
    // 256-wide window leaves the tensor pipe only ~31% utilized, the narrower QK wgmma is ~free while
    // finer 64-key tiles waste less compute past the window edge. STAGES=4 (CN=64 smem fits 5; the
    // window is only ~4 tiles, so a 4-deep K/V ring already covers it). Non-windowed hd128 keeps the
    // wide CN=128 tile (its gap is compute/barrier overlap, not register pressure -- CN=64 regressed it).
    else if (hd == 128 && hdv == 128) {
        if (pf_windowed && use_tma_contig) PF_DISPATCH(128, 128, 4, 64, 128);
        else                               PF_DISPATCH(128, 128, WS_STAGES, 128, 128);
    }
    else if (hd == 192 && hdv == 192) PF_DISPATCH(192, 192, 3, 64, 128);
    // hd256: register-bound, NOT pipeline-bound. HDV=256 forces acc_o[128]; CN>48 then overflows the
    // 232-reg consumer -> ptxas C7512 (wgmma serialized), slower despite wider tiles (CN=80->0.66,
    // CN=64->0.76). The K/V split-ring (decoupled free, KVSPLIT) was tried to add prefetch slack but at
    // CN=48 it regressed (0.823 vs 0.847: not pipeline-bound, the extra V-wait/free just adds barrier cost)
    // and at CN>48 it can't dodge C7512. So coupled CN=48/ST=3 is the local optimum; the gap to FA3's n80
    // is its tighter (CUTLASS) register allocation, not the pipeline. KVSPLIT stays off (default).
    else if (hd == 256 && hdv == 256) PF_DISPATCH(256, 256, 3, 48, 128);
    else TORCH_CHECK(false, "launch_prefill: unsupported hd/hdv ", hd, "/", hdv);
#undef PF_DISPATCH
#undef PF_DISPATCH_S
#undef PF_LAUNCH
}

